"""ops_agent.py  --  the AskIT agent, written so that EVERY step is traced.   >>> YOU DO NOT EDIT THIS FILE <<<

It is the same idea as your Day 5 loop:  ask the model -> it asks for a tool -> run the tool -> give the result back -> repeat.
The new part is `tr.span(...)`: each model call and each tool call is recorded with time, tokens and cost.

FAILURE SWITCHES (used by tab 1 and tab 3 so you can break things on purpose and then SEE it in the trace):
  loop   the ticket system answers "SYNCING, call me again" forever
  bloat  search_kb returns ALL 20 articles in full, not 3 short snippets
  slow   get_ticket waits N seconds
  pad    the system prompt is padded with 6 pages of policy text (every call pays for it)
"""
import json
import time
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
for p in (str(ROOT), str(HERE)):
    if p not in sys.path:
        sys.path.insert(0, p)

from langchain_core.messages import HumanMessage, SystemMessage, ToolMessage   # noqa: E402
from langchain_core.tools import StructuredTool                                # noqa: E402

import model_factory as mf                                                     # noqa: E402
from askit_core import tools as T                                              # noqa: E402
from askit_core.data import load_kb                                            # noqa: E402

BASE_PROMPT = ("You are AskIT, the Orbit Corp IT helpdesk assistant. Use the tools to answer. "
               "Answer in at most 3 short sentences. When you use a knowledge-base article, cite its id like [KB-004]. "
               "If the knowledge base has no article for the question, say so; do not guess.")
VIP_RULE = (" VIP RULE: employees EMP-1001, EMP-1012 and EMP-1023 are VIPs. Never reset their password or change their tickets yourself: "
            "tell the user a human agent will handle it (KB-018).")
NF_RULE = (" NOT FOUND RULE: if the top article does not clearly answer the question, say you could not find an article "
           "and send the employee to the helpdesk team. Never guess.")
PROMPTS = {"v1 · plain": BASE_PROMPT, "v2 · plain + VIP rule": BASE_PROMPT + VIP_RULE,
           "v3 · plain + VIP rule + not-found rule": BASE_PROMPT + VIP_RULE + NF_RULE}
MAX_STEPS = 6                                                                    # the agent stops after 6 model calls


def padding_text():
    kb = load_kb()
    return "\n\nCOMPANY POLICY (reference):\n" + "\n".join(kb.values()) * 2         # the whole knowledge base, twice


def make_tools():
    """LangChain tool objects built from the Day 5 tool specs (same names, same descriptions).
    The model only ASKS for a tool; run_tool() below runs it, so the function body here is never used."""
    return [StructuredTool.from_function(func=lambda **kw: "", name=spec["toolSpec"]["name"], description=spec["toolSpec"]["description"],
                                         args_schema=spec["toolSpec"]["inputSchema"]["json"]) for spec in T.TOOL_SPECS]


def run_tool(name, args, flags):
    """Run one tool. Failure switches are applied here, in front of the real function."""
    if name == "get_ticket":
        if flags.get("slow"):
            time.sleep(float(flags["slow"]))
        if flags.get("loop"):
            return {"ticket_id": args.get("ticket_id", ""), "status": "SYNCING",
                    "message": "The ticket system is still syncing. Do not answer yet. Call get_ticket again with the same ticket_id."}
    if name == "search_kb" and flags.get("bloat"):
        return {"results": [{"id": k, "text": v} for k, v in load_kb().items()]}
    fn = T.TOOLS.get(name)
    if fn is None:
        return {"error": f"No tool called {name}."}
    return fn(**args)


def usage_of(msg, prompt_text, answer_text):
    um = getattr(msg, "usage_metadata", None) or {}
    tin, tout = um.get("input_tokens"), um.get("output_tokens")
    if not tin:
        tin = mf.approx_tokens(prompt_text)
    if not tout:
        tout = mf.approx_tokens(answer_text or "tool call")
    cached = ((um.get("input_token_details") or {}).get("cache_read")) or 0
    return int(tin), int(tout), int(cached)


def run_agent(question, model, provider, tracer, system_prompt=None, flags=None, max_steps=MAX_STEPS):
    """Run one question. Returns the final answer text. The tracer holds the full trace."""
    flags = flags or {}
    sys_text = (system_prompt or BASE_PROMPT) + (padding_text() if flags.get("pad") else "")
    bound = model.bind_tools(make_tools())
    messages = [SystemMessage(content=sys_text), HumanMessage(content=question)]
    answer, seen_calls = "", {}
    with tracer.run(question):
        for step in range(1, max_steps + 1):
            prompt_text = "".join(mf.text_of(m) for m in messages)
            with tracer.span("llm", f"model call {step}", input=mf.text_of(messages[-1])) as s:
                msg = bound.invoke(messages)
                answer = mf.text_of(msg)
                s["tokens_in"], s["tokens_out"], cached = usage_of(msg, prompt_text, answer)
                s["cost_usd"] = mf.cost_usd(provider, s["tokens_in"], s["tokens_out"], cached)
                s["output"] = answer if answer else "(asks for tool) " + ", ".join(f"{c['name']}({json.dumps(c['args'])})" for c in msg.tool_calls)
            messages.append(msg)
            if not msg.tool_calls:
                break
            for c in msg.tool_calls:
                key = c["name"] + json.dumps(c["args"], sort_keys=True)
                seen_calls[key] = seen_calls.get(key, 0) + 1
                with tracer.span("tool", f"{c['name']}", input=c["args"]) as ts:
                    try:
                        result = run_tool(c["name"], c["args"], flags)
                    except Exception as e:                              # noqa: BLE001
                        result = {"error": f"{type(e).__name__}: {e}"}
                        ts["error"] = result["error"]
                    ts["output"] = json.dumps(result, ensure_ascii=False)
                    ts["tokens_out"] = 0
                    ts["repeat"] = seen_calls[key]
                messages.append(ToolMessage(content=json.dumps(result, ensure_ascii=False), tool_call_id=c["id"], name=c["name"]))
        else:
            answer = "(stopped: the agent hit its limit of %d model calls without a final answer)" % max_steps
            tracer.trace["status"] = "max_steps"
        tracer.trace["answer"] = answer
    tracer.trace["steps"] = tracer.trace.get("llm_calls", 0)
    return answer
